mapper.select:
SELECT A.LOG_NO, A.USER_ID, A.PLAN_NO, A.IS_PLAN, A.SCRIPT_NO, A.SCRIPT_TYPE, A.SCRIPT_UNIT, A.SCRIPT_TITLE, A.SECTION_NO, A.CHIME_START_NO, A.CHIME_START_CNT, A.CHIME_END_NO, A.CHIME_END_CNT, A.SCRIPT_BODY, A.SCRIPT_BODY_CNT, A.SCRIPT_RECORD_FILE, A.SCRIPT_TIMESTAMP, A.TRANS_VOLUME, A.LOG_TYPE, A.LOG_DATE, A.MOBILE_SEND_USER, B.TRANS_START, B.TRANS_CHECK, B.TRANS_FLAG, B.TRANS_ERROR, B.RTU_ID, (SELECT COUNT(LOG_NO) FROM RTU_LOG WHERE LOG_NO = A.LOG_NO AND (TRANS_FLAG = '99' OR ((TRANS_FLAG = '30' OR TRANS_FLAG = '40') AND (TRANS_ERROR = '13' OR TRANS_ERROR = '14' OR TRANS_ERROR = '15')))) AS RTU_CNT_OK,
(SELECT COUNT(LOG_NO) FROM RTU_LOG WHERE LOG_NO = A.LOG_NO AND VHF_CALL = '7') AS RTU_CNT_VHF_OK,
(SELECT COUNT(LOG_NO) FROM RTU_LOG WHERE LOG_NO = A.LOG_NO AND TRANS_FLAG = '20' AND TRANS_ERROR = '88') AS RTU_CNT_CRO_OK,
(SELECT COUNT(LOG_NO) FROM RTU_LOG WHERE LOG_NO = A.LOG_NO) AS RTU_CNT, (SELECT SECTION_NAME FROM BROADCAST_SECTION WHERE SECTION_NO = A.SECTION_NO) AS SECTION_NAME FROM BROADCAST_LOG AS A LEFT JOIN RTU_LOG AS B ON A.LOG_NO = B.LOG_NO WHERE A.ORGAN_ID = #{organ_id} AND A.LOG_TYPE = '0'
AND A.LOG_DATE BETWEEN #{sdate} AND #{edate}
AND A.IS_PLAN = #{is_plan}
AND A.USER_ID LIKE CONCAT('%',#{user_id},'%')
GROUP BY A.LOG_NO ORDER BY A.LOG_DATE DESC
LIMIT 0, #{alarm_cnt}

mapper.insert:

 INSERT INTO BROADCAST_LOG ( 
	LOG_NO, ORGAN_ID, USER_ID 
	, LOG_TYPE , LOG_DATE, VALID 
	, RTU_CNT
	, IS_PLAN
	, SCRIPT_NO
	, SCRIPT_TYPE
	, SCRIPT_UNIT
	, SECTION_NO
	, SCRIPT_TITLE
	, CHIME_START_NO
	, CHIME_START_CNT
	, CHIME_END_NO
	, CHIME_END_CNT
	, SCRIPT_BODY
	, SCRIPT_BODY_CNT
	, SCRIPT_RECORD_FILE
	, SCRIPT_TIMESTAMP
	, TRANS_VOLUME
	, BROAD_IP
	, MOBILE_SEND_USER
	, SCRIPT_PLAY_SECONDS
	, VHF_MSG_GRP
	) VALUES ( 
		(SELECT IFNULL( MAX(LOG_NO) + 1, 1 ) AS log_no
		 FROM BROADCAST_LOG AS ALIAS_FOR_SUBQUERY)
		 , #{organ_id}, #{user_id}
		 , #{log_type}, now(), #{valid} 
	, #{rtu_cnt}
	, #{is_plan}
	, #{script_no}
	, #{script_type}
	, #{script_unit}
	, #{section_no}
	, #{script_title}
	, #{chime_start_no}
	, #{chime_start_cnt}
	, #{chime_end_no}
	, #{chime_end_cnt}
	, #{script_body}
	, #{script_body_cnt}
	, #{script_record_file}
	, date_format(now(), '%Y%m%d%H%i%S')
	, #{trans_volume}
	, #{broad_ip}
	, #{mobile_send_user}
	, #{script_play_seconds}
	, #{vhf_msg_grp}
	)


 INSERT INTO BROADCAST_SCRIPT ( 
	SCRIPT_NO, ORGAN_ID, USER_ID 
	, SCRIPT_TIMESTAMP 
	, OWN_TYPE
	, SCRIPT_UNIT
	, SECTION_NO
	, SCRIPT_TITLE
	, CHIME_START_NO
	, CHIME_START_CNT
	, CHIME_END_NO
	, CHIME_END_CNT
	, SCRIPT_BODY
	, SCRIPT_BODY_CNT
	, SCRIPT_RECORD_FILE
	, TRANS_VOLUME
	, SCRIPT_PLAY_SECONDS
	, SCRIPT_SORT
	) VALUES ( 
		(SELECT IFNULL( MAX(SCRIPT_NO) + 1, 1 ) AS script_no
		 FROM BROADCAST_SCRIPT AS ALIAS_FOR_SUBQUERY)
		 , #{organ_id}, #{user_id}
		 , date_format(now(), '%Y%m%d%H%i%S')
	, #{own_type}
	, #{script_unit}
	, #{section_no}
	, #{script_title}
	, #{chime_start_no}
	, #{chime_start_cnt}
	, #{chime_end_no}
	, #{chime_end_cnt}
	, #{script_body}
	, #{script_body_cnt}
	, #{script_record_file}
	, #{trans_volume}
	, #{script_play_seconds}
	, #{script_sort}
	)

mapper.update:

 UPDATE BROADCAST_SCRIPT SET 
 	 ORGAN_ID = #{organ_id}, USER_ID = #{user_id}
	, OWN_TYPE = #{own_type}
	, SCRIPT_UNIT = #{script_unit}
	, SECTION_NO = #{section_no}
	, SCRIPT_TITLE = #{script_title}
	, CHIME_START_NO = #{chime_start_no}
	, CHIME_START_CNT = #{chime_start_cnt}
	, CHIME_END_NO = #{chime_end_no}
	, CHIME_END_CNT = #{chime_end_cnt}
	, SCRIPT_BODY = #{script_body}
	, SCRIPT_BODY_CNT = #{script_body_cnt}
	, SCRIPT_RECORD_FILE = #{script_record_file}
	, TRANS_VOLUME = #{trans_volume}
	, SCRIPT_PLAY_SECONDS = #{script_play_seconds}
	, SCRIPT_SORT = #{script_sort}
WHERE SCRIPT_NO = #{script_no}


  UPDATE BROADCAST_PLAN SET
   	ORGAN_ID = #{organ_id}, USER_ID = #{user_id}
	, RTU_CNT = #{rtu_cnt}
	, SCRIPT_NO = #{script_no}
	, SCRIPT_TYPE = #{script_type}
	, SCRIPT_UNIT = #{script_unit}
	, SECTION_NO = #{section_no}
	, SCRIPT_TITLE = #{script_title}
	, CHIME_START_NO = #{chime_start_no}
	, CHIME_START_CNT = #{chime_start_cnt}
	, CHIME_END_NO = #{chime_end_no}
	, CHIME_END_CNT = #{chime_end_cnt}
	, SCRIPT_BODY = #{script_body}
	, SCRIPT_BODY_CNT = #{script_body_cnt}
	, SCRIPT_RECORD_FILE = #{script_record_file}
	, SCRIPT_TIMESTAMP = date_format(now(), '%Y%m%d%H%i%S')
	, TRANS_VOLUME = #{trans_volume}
	, SCRIPT_PLAY_SECONDS = #{script_play_seconds}
	, PLAN_CYCLE = #{plan_cycle}
	, IS_PAUSE = #{is_pause}
	, PLAN_START_DATE = #{plan_start_date}
	, PLAN_END_DATE = #{plan_end_date}
	, VHF_MSG_GRP = #{vhf_msg_grp}
WHERE PLAN_NO = #{plan_no}
